import catalog from "@/lib/decor-catalog.json";
import { monthlyImpact } from "@/lib/home-data";

/** A rectangle on a tilesheet, in source pixels. */
export type SpriteRect = { x: number; y: number; w: number; h: number };

/** One sprite on a single-view sheet (the garden), generated by scripts/build-decor.mjs. */
export type DecorGeometry = SpriteRect & {
  id: string;
  name: string;
  category: string;
};

/**
 * One view of an object. `facing` is the direction the object points, in turn
 * order: front, right, back, left. Objects drawn only once have a single
 * "front" variant, so nothing has to special-case them.
 */
export type DecorVariant = SpriteRect & { facing: string };

/**
 * One object in the interiors catalogue, with every view of it the sheet
 * provides. Four-facing pieces are one entry rather than four, so the workshop
 * lists "Armchair" once and the resident turns it after placing it.
 */
export type DecorEntry = {
  id: string;
  name: string;
  category: string;
  variants: DecorVariant[];
};

type SheetOf<Item> = {
  sheet: string;
  sheetWidth: number;
  sheetHeight: number;
  tile: number;
  items: Item[];
};

/** Single-view sheet, as the garden backdrops read it. */
export type DecorSheet = SheetOf<DecorGeometry>;

/**
 * The wooden border drawn around the room, nine-sliced into `dir` as
 * tl/tr/bl/br corners and top/bottom/left/right 1px repeating strips. `rect`
 * records where on the sheet it was cut from, for build tooling only.
 */
export type LiningSlices = { inset: number; dir: string; rect: SpriteRect };

export type InteriorSheet = SheetOf<DecorEntry> & { lining: LiningSlices };

export const decorSheet = catalog as InteriorSheet;
export const TILE = decorSheet.tile;
export const LINING = decorSheet.lining;

/**
 * Pick a view, wrapping so a rotate control can just keep incrementing and a
 * saved facing survives an entry losing a variant.
 */
export function variantOf(item: DecorEntry, facing: number): DecorVariant {
  const count = item.variants.length;
  const index = ((Math.trunc(facing) % count) + count) % count;
  return item.variants[index];
}

/** Where an item is allowed to sit in the room. */
export type PlacementLayer = "wall" | "floor";

// ---------------------------------------------------------------------------
// Materials
// ---------------------------------------------------------------------------

export type MaterialId =
  | "cardboard"
  | "petBottle"
  | "glassBottle"
  | "metalCan"
  | "woodOffcut"
  | "garment";

export type MaterialDef = {
  id: MaterialId;
  /** Singular noun, e.g. "cardboard box". */
  name: string;
  /** Plural noun, e.g. "cardboard boxes". */
  plural: string;
  /** Matches an id in monthlyImpact.wasteSources, so counts come from real data. */
  sourceId: string;
  /**
   * Typical mass of one item, used to turn the kg the app already tracks into
   * a countable number of things. Approximate by nature — a drinks bottle and
   * a shampoo bottle are both "a PET bottle".
   */
  unitKg: number;
  /** Short symbol for the compact wallet chips. */
  symbol: string;
};

