const FALLBACK: DecorRules = {
  layer: "floor",
  cost: {},
  fact: "Every item kept in use is one that does not need making again.",
};

export type DecorItem = DecorEntry & DecorRules;

export const decorItems: DecorItem[] = decorSheet.items.map((item) => ({
  ...item,
  ...(RULES[item.id] ?? FALLBACK),
}));

export const decorById = new Map(decorItems.map((item) => [item.id, item]));

/**
 * Surfaces the room paints itself with rather than things to place in it. They
 * stay in the manifest because the room tiles its wall and floor from their
 * rectangles, but listing them would offer the resident a single floor tile to
 * drag onto a floor already made of it. The blue drape is not one of these —
 * it is a hanging you put on a wall, so it stays in the catalogue.
 */
const SURFACE_IDS = new Set(["wall-stone", "floor-wood", "floor-concrete"]);

/** The catalogue as the workshop shows it: placeable objects only. */
export const placeableItems = decorItems.filter((item) => !SURFACE_IDS.has(item.id));

/** Items that cost nothing — available before any exchange. */
export const starterIds = decorItems.filter((item) => isFree(item.cost)).map((i) => i.id);

/** Human-readable cost, e.g. "8 cardboard boxes and 2 wood offcuts". */
export function describeCost(cost: MaterialCost): string {
  const parts = (Object.entries(cost) as [MaterialId, number][]).map(
    ([material, amount]) => {
      const def = materialById.get(material);
      if (!def) return `${amount}`;
      return `${amount} ${amount === 1 ? def.name : def.plural}`;
    },
  );
  if (parts.length === 0) return "Free";
  if (parts.length === 1) return parts[0];
  return `${parts.slice(0, -1).join(", ")} and ${parts[parts.length - 1]}`;
}
